import assert from 'node:assert/strict';
import test from 'node:test';
import { billableWeightGrams, isShippable, VOLUMETRIC_DIVISOR } from '../lib/parcels.js';

test('bills the actual weight of a small heavy parcel', () => {
  assert.equal(billableWeightGrams({ lengthCm: 10, widthCm: 10, heightCm: 10, weightGrams: 2000 }), 2000);
});

test('bills the volumetric weight of a large light parcel', () => {
  const parcel = { lengthCm: 50, widthCm: 40, heightCm: 30, weightGrams: 1000 };
  assert.equal(billableWeightGrams(parcel), (50 * 40 * 30 * 1000) / VOLUMETRIC_DIVISOR);
});

test('rounds the volumetric weight up to the gram', () => {
  const parcel = { lengthCm: 7, widthCm: 7, heightCm: 7, weightGrams: 1 };
  assert.equal(billableWeightGrams(parcel), Math.ceil((7 * 7 * 7 * 1000) / VOLUMETRIC_DIVISOR));
});

test('takes parcels up to 30 kg and refuses heavier ones', () => {
  const parcel = { lengthCm: 50, widthCm: 40, heightCm: 30 };
  assert.equal(isShippable({ ...parcel, weightGrams: 30_000 }), true);
  assert.equal(isShippable({ ...parcel, weightGrams: 30_001 }), false);
});
# shipping-service

Buys carrier labels for the shop's orders and quotes their shipping costs. It has no dependencies: it runs on Node.js 22 or later alone.

`npm test` runs the tests in `test/`. The carrier is never called by a test: each one passes a fake transport.

| Path | Holds |
|---|---|
| `lib/labels.js` | Carrier labels for shipments |
| `lib/rates.js` | Shipping costs and the carrier's rate quotes |
| `lib/parcels.js` | Parcel weights |
| `lib/addresses.js` | Address lines |
| `lib/tracking.js` | Tracking numbers and shipment statuses |
| `lib/notifications.js` | Emails to customers |
| `lib/carrier.js` | Requests to the carrier API, through a transport that makes the HTTP call |
| `lib/retry.js` | Retries of carrier requests |
| `lib/config.js` | Settings read from environment variables |
