python3 - <<'EOF'
p='lib/parcels.js'
s=open(p).read()
s=s.replace('''/** Divides a parcel's volume in cubic centimetres to give its volumetric weight in kilograms. */
export const VOLUMETRIC_DIVISOR = 6000;
''','''/**
 * The volumetric divisors the carrier has applied to our account, newest first. Each applies to parcels shipped
 * from its date (00:00 UTC) on. The first one is the divisor the account started with.
 */
const DIVISOR_SCHEDULE = [
  { from: Date.UTC(2026, 6, 1), divisor: 6000 },
  { from: Date.UTC(2026, 3, 1), divisor: 4000 },
  { from: -Infinity, divisor: 5000 },
];

/** Divides a parcel's volume in cubic centimetres to give its volumetric weight in kilograms. This is the current one. */
export const VOLUMETRIC_DIVISOR = DIVISOR_SCHEDULE[0].divisor;
''')
s=s.replace('''/** Returns the weight the carrier bills for a parcel, in grams: its actual or its volumetric weight, whichever is higher. */
export function billableWeightGrams(parcel) {''','''/** Returns the volumetric divisor that applied to a parcel shipped on the given Date. */
export function volumetricDivisorOn(date) {
  const time = date.getTime();
  if (Number.isNaN(time)) throw new TypeError('volumetricDivisorOn needs a valid Date');
  return DIVISOR_SCHEDULE.find((entry) => time >= entry.from).divisor;
}

/**
 * Returns the weight the carrier bills for a parcel, in grams: its actual or its volumetric weight, whichever is higher.
 * The volumetric weight uses the divisor of the day the parcel shipped, which defaults to now.
 */
export function billableWeightGrams(parcel, shippedOn = new Date()) {''')
s=s.replace("(volumeCm3 * 1000) / VOLUMETRIC_DIVISOR)","(volumeCm3 * 1000) / volumetricDivisorOn(shippedOn))")
open(p,'w').write(s)

p='test/parcels.test.js'
s=open(p).read()
s=s.replace("isShippable, VOLUMETRIC_DIVISOR }","isShippable, VOLUMETRIC_DIVISOR, volumetricDivisorOn }")
s+='''
test('uses the divisor in force on the day a parcel shipped', () => {
  assert.equal(volumetricDivisorOn(new Date('2026-03-02T00:00:00Z')), 5000);
  assert.equal(volumetricDivisorOn(new Date('2026-03-31T23:59:59.999Z')), 5000);
  assert.equal(volumetricDivisorOn(new Date('2026-04-01T00:00:00Z')), 4000);
  assert.equal(volumetricDivisorOn(new Date('2026-06-30T23:59:59.999Z')), 4000);
  assert.equal(volumetricDivisorOn(new Date('2026-07-01T00:00:00Z')), 6000);
  assert.equal(volumetricDivisorOn(new Date('2026-11-27T12:00:00Z')), 6000);
});

test('bills a past parcel with the divisor of its shipping day', () => {
  const parcel = { lengthCm: 50, widthCm: 40, heightCm: 30, weightGrams: 1000 };
  assert.equal(billableWeightGrams(parcel, new Date('2026-03-15T10:00:00Z')), 12_000);
  assert.equal(billableWeightGrams(parcel, new Date('2026-05-15T10:00:00Z')), 15_000);
  assert.equal(billableWeightGrams(parcel, new Date('2026-07-15T10:00:00Z')), 10_000);
});

test('rounds a past volumetric weight up too', () => {
  const parcel = { lengthCm: 7, widthCm: 7, heightCm: 7, weightGrams: 1 };
  assert.equal(billableWeightGrams(parcel, new Date('2026-03-15T10:00:00Z')), 69); // 68.6 up
});
'''
open(p,'w').write(s)
EOF
